  assert.deepEqual(resolve(registry, { a: '*' }), { a: '1.0.0' });
  assert.equal(resolve(registry, { a: '2.0.0' }), null);
});

test('long dependency chains do not depend on stack depth or iteration limits', () => {
  const count = 15000;
  const registry = {};
  for (let i = 0; i < count; i += 1) {
    registry[`p${i}`] = { '1.0.0': i + 1 < count ? { [`p${i + 1}`]: '*' } : {} };
