'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { parse, compare, satisfies, compileRange } = require('./src/semver');

 test('numeric candidate ordering covers every component', () => {
  const registry = { a: { '2.0.0': {}, '10.0.0': {}, '10.9.0': {}, '10.10.9': {}, '10.10.10': {} } };
  assert.deepEqual(resolve(registry, { a: '*' }), { a: '10.10.10' });
});

test('failed choices undo dependencies, constraints, and queued names', () => {
  const registry = {
    a: { '2.0.0': { b: '2.0.0', ghost: '*' }, '1.0.0': { b: '1.0.0' } },
    b: { '2.0.0': { absent: '*' }, '1.0.0': {} },
    ghost: { '1.0.0': {} },
  };
  assert.deepEqual(resolve(registry, { a: '*' }), { a: '1.0.0', b: '1.0.0' });
});

test('FIFO first-found selection is not global version maximization', () => {
  const registry = {
    a: { '2.0.0': { c: '1.0.0' }, '1.0.0': { c: '2.0.0' } },
    b: { '2.0.0': { c: '2.0.0' }, '1.0.0': { c: '1.0.0' } },
    c: { '2.0.0': {}, '1.0.0': {} },
  };
  assert.deepEqual(resolve(registry, { a: '*', b: '*' }), { a: '2.0.0', b: '1.0.0', c: '1.0.0' });
  assert.deepEqual(resolve(registry, { b: '*', a: '*' }), { b: '2.0.0', a: '1.0.0', c: '2.0.0' });
});

test('selected-version dependency key order determines subsequent choices', () => {
  const registry = {
    start: { '1.0.0': { b: '*', a: '*' } },
    a: { '2.0.0': { c: '1.0.0' }, '1.0.0': { c: '2.0.0' } },
    b: { '2.0.0': { c: '2.0.0' }, '1.0.0': { c: '1.0.0' } },
    c: { '2.0.0': {}, '1.0.0': {} },
  };
  assert.deepEqual(resolve(registry, { start: '*' }), { start: '1.0.0', b: '2.0.0', a: '1.0.0', c: '2.0.0' });
});

test('later dependencies can backtrack earlier selected packages', () => {
  const registry = {
    a: { '2.0.0': {}, '1.0.0': {} },
    b: { '1.0.0': { a: '1.0.0' } },
  };
  assert.deepEqual(resolve(registry, { a: '*', b: '*' }), { a: '1.0.0', b: '1.0.0' });
});

test('cycles and repeated discovery expand each selected package once', () => {
  const registry = {
    a: { '1.0.0': { b: '*', a: '*' } },
    b: { '1.0.0': { a: '*' } },
  };
  assert.deepEqual(resolve(registry, { a: '*', b: '*' }), { a: '1.0.0', b: '1.0.0' });
});

test('self conflicts restore constraints before trying a lower version', () => {
  const registry = { a: { '2.0.0': { a: '1.0.0' }, '1.0.0': { a: '*' } } };
  assert.deepEqual(resolve(registry, { a: '*' }), { a: '1.0.0' });
  assert.equal(resolve(registry, { a: '2.0.0' }), null);
});

test('long dependency chains do not depend on stack depth or iteration limits', () => {
  const count = 15000;
  const registry = {};
  for (let i = 0; i < count; i += 1) {
    registry[`p${i}`] = { '1.0.0': i + 1 < count ? { [`p${i + 1}`]: '*' } : {} };
  }
  const result = resolve(registry, { p0: '*' });
  assert.notEqual(result, null);
  assert.equal(Object.keys(result).length, count);
  for (let i = 0; i < count; i += 1) assert.equal(result[`p${i}`], '1.0.0');
});

test('discovered conflicts prune before enumerating independent choices', { timeout: 2000 }, () => {
  const registry = { gate: { '1.0.0': {}, '2.0.0': {} } };
  const root = {};
  for (let i = 0; i < 30; i += 1) {
    registry[`p${i}`] = { '2.0.0': { gate: '2.0.0' }, '1.0.0': { gate: '2.0.0' } };
    root[`p${i}`] = '*';
  }
  root.gate = '1.0.0';
  assert.equal(resolve(registry, root), null);
});

test('missing packages are unsatisfiable; unreachable packages are not selected', () => {
