test('self conflicts restore constraints before trying a lower version', () => {
  const registry = { a: { '2.0.0': { a: '1.0.0' }, '1.0.0': { a: '*' } } };
  assert.deepEqual(resolve(registry, { a: '*' }), { a: '1.0.0' });
  assert.equal(resolve(registry, { a: '2.0.0' }), null);
});

test('long dependency chains do not depend on stack depth or iteration limits', () => {
  const count = 15000;
  const registry = {};
  for (let i = 0; i < count; i += 1) {
    registry[`p${i}`] = { '1.0.0': i + 1 < count ? { [`p${i + 1}`]: '*' } : {} };
  }
  const result = resolve(registry, { p0: '*' });
  assert.notEqual(result, null);
  assert.equal(Object.keys(result).length, count);
  for (let i = 0; i < count; i += 1) assert.equal(result[`p${i}`], '1.0.0');
});

test('discovered conflicts prune before enumerating independent choices', { timeout: 2000 }, () => {
  const registry = {
    gate: { '1.0.0': {}, '2.0.0': {} },
    p0: { '2.0.0': { gate: '2.0.0' }, '1.0.0': { gate: '1.0.0' } },
  };
  const root = { p0: '*' };
  const expected = { p0: '1.0.0' };
  for (let i = 1; i < 30; i += 1) {
    registry[`p${i}`] = { '2.0.0': {}, '1.0.0': {} };
    root[`p${i}`] = '*';
    expected[`p${i}`] = '2.0.0';
  }
  root.gate = '1.0.0';
  expected.gate = '1.0.0';
  assert.deepEqual(resolve(registry, root), expected);
test('missing packages are unsatisfiable; unreachable packages are not selected', () => {
  assert.equal(resolve({}, { absent: '*' }), null);
  assert.deepEqual(resolve({ unused: { '1.0.0': { absent: '*' } } }, {}), {});
});

test('all registry maps, versions, and ranges are validated eagerly', () => {
  for (const registry of [
    { unused: [] },
    { unused: { '01.0.0': {} } },
    { unused: { '1.0.0\n': {} } },
    { unused: { '1.0.0': null } },
    { unused: { '1.0.0': { dependency: '^invalid' } } },
  ]) assert.throws(() => resolve(registry, {}), TypeError);
