test('caret and tilde enforce inclusive bases and exclusive component boundaries', () => {
  const cases = [
    ['^1.2.3', '1.2.2', false], ['^1.2.3', '1.2.3', true], ['^1.2.3', '1.99.0', true], ['^1.2.3', '2.0.0', false],
