    ['^0.0.3', '0.0.2', false], ['^0.0.3', '0.0.3', true], ['^0.0.3', '0.0.4', false],
    ['^0.0.0', '0.0.0', true], ['^0.0.0', '0.0.1', false],
    ['~0.0.3', '0.0.2', false], ['~0.0.3', '0.0.99', true], ['~0.0.3', '0.1.0', false],
    ['^9007199254740991.0.0', '9007199254740991.99.0', true],
